   862	read_request_finalizer(size_t total_read,
   863	                       size_t buffer_size,
   864	                       struct lwan_request_parser_helper *helper,
   865	                       int n_packets)
   866	{
   867	    /* 16 packets should be enough to read a request (without the body, as
   868	     * is the case for POST requests).  This yields a timeout error to avoid
   869	     * clients being intentionally slow and hogging the server.  */
   870	    if (UNLIKELY(n_packets > helper->error_when_n_packets))
   871	        return FINALIZER_ERROR_TIMEOUT;
   872	
   873	    if (UNLIKELY(total_read < 4))
   874	        return FINALIZER_YIELD_TRY_AGAIN;
   875	
   876	    if (UNLIKELY(total_read == buffer_size))
   877	        return FINALIZER_ERROR_TOO_LARGE;
   878	
   879	    if (LIKELY(helper->next_request)) {
   880	        helper->next_request = NULL;
   881	        return FINALIZER_DONE;
   882	    }
   883	
   884	    /* FIXME: Would saving the location of CRLFCRLF be useful? Maybe
   885	     * parse_headers() could benefit from this information?  How would it
   886	     * compare to helper->next_request?  */
   887	    if (LIKELY(memmem(helper->buffer->value, helper->buffer->len, "\r\n\r\n", 4)))
   888	        return FINALIZER_DONE;
   889	
   890	    return FINALIZER_TRY_AGAIN;
   891	}
